public class Main {
    static String encode(String s) {
        StringBuilder sb = new StringBuilder();
        int i = 0;
        while (i < s.length()) {
            char c = s.charAt(i);
            int run = 0;
            while (i < s.length() && s.charAt(i) == c) {
                run++;
                i++;
            }
            sb.append(c).append(run);
        }
        return sb.toString();
    }

    public static void main(String[] args) {
        System.out.println(encode("aaabccdddd"));
    }
}
